{
  "root_causes": [
    {
      "service": "ts-train-food-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_pod_name AS pod, min(time) AS first_seen, max(time) AS last_seen, count(*) AS spans FROM abnormal_traces WHERE service_name='ts-train-food-service' GROUP BY 1 ORDER BY 2",
          "claim": "Original train-food pod stops emitting at 05:58:09; a replacement pod first appears at about 05:59:12 and keeps running."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) FILTER (WHERE attr_status_code='Error') AS failed_calls, count(*) AS calls FROM abnormal_traces WHERE service_name='ts-food-service' AND span_name='GET' AND attr_span_kind='Client' GROUP BY 1 ORDER BY 1",
          "claim": "Food-service calls to train-food fail only in the 05:58–05:59 window, then succeed again from 06:00."
        },
        {
          "kind": "log",
          "sql": "SELECT min(time) AS t0, max(time) AS t1, count(*) AS n FROM abnormal_logs WHERE service_name='ts-food-service' AND attr_log_template ILIKE '%Connection refused%'",
          "claim": "ts-food-service logs 108 'Connection refused' exceptions between 05:58:12 and 05:59:19, matching the train-food outage."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, min(value) AS vmin, max(value) AS vmax, count(*) AS n FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name ILIKE '%train-food%' GROUP BY 1",
          "claim": "Restart counters for train-food pods stay at 0, so the outage was a pod replacement rather than a container restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
