        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND (attr_status_code='Error' OR attr_http_response_status_code>=400) GROUP BY ALL",
          "claim": "ts-ui-dashboard returns 108 HTTP 500 responses on the /api/v1/foodservice/foods endpoint; none appear in the normal period."
